import {
    HEVC_EXACT_CAPABILITY_TIERS,
    HEVC_EXACT_CAPABILITY_TIER_DEFINITIONS,
    type HEVCExactCapabilityTier,
    type HEVCExactCapabilityWorkerTierRequest
} from './HEVCExactCapabilityProtocol';

const MAIN_1080P_ACCESS_UNIT_SHA256 =
    '55a926204c9eb76a1b36be2332fc2195bda8f78c9d3bda869b9abbcc367832d4';
const MAIN10_1080P_ACCESS_UNIT_SHA256 =
    '67c3c7a788c076a9e71c82ad8204d1403bee29e99f7ad37b59be25da6fad398e';
const MAIN10_4K_ACCESS_UNIT_SHA256 =
    '05d0c0c34602949c95be9974c3b62275f1de0f803fa84cd8eb42806c6fa09a0d';

const MAIN_1080P_QUALIFICATION_BITSTREAM_SHA256 =
    '2166e4c47e4285cae391d360b7fb794c2364c528ee6db1860ed957d09e3f61c7';
const MAIN10_1080P_QUALIFICATION_BITSTREAM_SHA256 =
    '2e08094f02875d4e2855771120013f9688a3105e719588ce7f51121ef67eca21';
const MAIN10_4K_QUALIFICATION_BITSTREAM_SHA256 =
    '0b320b24dbecb054276fcf4412c8ad24f9f3478d2f406f86410ad46869acce7b';

// Regeneration recipe using FFmpeg git-862338fe31 and x265 4.1+225-1b48507eb
// PowerShell: $common = 'high-tier=0:keyint=30:min-keyint=1:scenecut=0:bframes=0:' +
// 'repeat-headers=1:annexb=1:info=0:pools=1:frame-threads=1:wpp=0'
// ffmpeg -f lavfi -i "color=c=black:s=1920x1080:r=1" -frames:v 1 -pix_fmt yuv420p `
// -c:v libx265 -profile:v main -preset ultrafast -x265-params "level-idc=4.0:$common" `
// -f hevc -y hevc-main-1080p.hevc
// ffmpeg -f lavfi -i "color=c=black:s=1920x1080:r=1" -frames:v 1 -pix_fmt yuv420p10le `
// -c:v libx265 -profile:v main10 -preset ultrafast -x265-params "level-idc=4.0:$common" `
// -f hevc -y hevc-main10-1080p.hevc
// ffmpeg -f lavfi -i "color=c=black:s=3840x2160:r=1" -frames:v 1 -pix_fmt yuv420p10le `
// -c:v libx265 -profile:v main10 -preset ultrafast -x265-params "level-idc=5.1:$common" `
// -f hevc -y hevc-main10-4k.hevc
// PowerShell: $qualification = 'high-tier=0:keyint=2:min-keyint=2:scenecut=0:' +
// 'bframes=0:open-gop=0:repeat-headers=1:annexb=1:info=0:pools=1:' +
// 'frame-threads=1:wpp=0'
// Use -i "smptebars=s=<size>:r=30:d=0.267,scroll=h=0.01" and -frames:v 8
// with the same output format, profile, and level commands above
const MAIN_1080P_ACCESS_UNIT_BASE64 =
    '';
const MAIN10_1080P_ACCESS_UNIT_BASE64 =
    '';
const MAIN10_4K_ACCESS_UNIT_BASE64 =
    '';

const MAIN_1080P_QUALIFICATION_BITSTREAM_BASE64 =
    '';
const MAIN10_1080P_QUALIFICATION_BITSTREAM_BASE64 =
    '';
const MAIN10_4K_QUALIFICATION_BITSTREAM_BASE64 =
    '';

const ACCESS_UNIT_BASE64: Readonly<Record<HEVCExactCapabilityTier, string>> = Object.freeze({
    'main-1080p': MAIN_1080P_ACCESS_UNIT_BASE64,
    'main10-1080p': MAIN10_1080P_ACCESS_UNIT_BASE64,
    'main10-4k': MAIN10_4K_ACCESS_UNIT_BASE64
});

const INLINE_QUALIFICATION_BITSTREAM_BASE64: Readonly<Partial<Record<
    HEVCExactCapabilityTier,
    string
>>> = Object.freeze({
    'main-1080p': MAIN_1080P_QUALIFICATION_BITSTREAM_BASE64,
    'main10-1080p': MAIN10_1080P_QUALIFICATION_BITSTREAM_BASE64,
    'main10-4k': MAIN10_4K_QUALIFICATION_BITSTREAM_BASE64
});

export const HEVC_EXACT_CAPABILITY_ACCESS_UNIT_SHA256: Readonly<Record<
    HEVCExactCapabilityTier,
    string
>> = Object.freeze({
    'main-1080p': MAIN_1080P_ACCESS_UNIT_SHA256,
    'main10-1080p': MAIN10_1080P_ACCESS_UNIT_SHA256,
    'main10-4k': MAIN10_4K_ACCESS_UNIT_SHA256
});

export const HEVC_EXACT_CAPABILITY_QUALIFICATION_BITSTREAM_SHA256: Readonly<Record<
    HEVCExactCapabilityTier,
    string
>> = Object.freeze({
    'main-1080p': MAIN_1080P_QUALIFICATION_BITSTREAM_SHA256,
    'main10-1080p': MAIN10_1080P_QUALIFICATION_BITSTREAM_SHA256,
    'main10-4k': MAIN10_4K_QUALIFICATION_BITSTREAM_SHA256
});

function decodeBase64(value: string): Uint8Array {
    if (typeof globalThis.atob !== 'function') {
        throw new Error('Base64 decoding is unavailable for the HEVC capability fixture');
    }
    const decoded = globalThis.atob(value);
    const bytes = new Uint8Array(decoded.length);
    for (let byteIndex = 0; byteIndex < decoded.length; byteIndex += 1) {
        bytes[byteIndex] = decoded.charCodeAt(byteIndex);
    }
    return bytes;
}

function createTransferableBuffer(bytes: Uint8Array): ArrayBuffer {
    const buffer = new ArrayBuffer(bytes.byteLength);
    new Uint8Array(buffer).set(bytes);
    return buffer;
}

function createQualificationAccessUnits(
    tier: HEVCExactCapabilityTier,
    main10UltraHDQualificationBitstream: ArrayBuffer
): readonly ArrayBuffer[] {
    const inlineBitstream = tier === 'main10-4k' ?
        undefined :
        INLINE_QUALIFICATION_BITSTREAM_BASE64[tier];
    const bitstream = inlineBitstream === undefined ?
        new Uint8Array(main10UltraHDQualificationBitstream) :
        decodeBase64(inlineBitstream);
    const byteLengths = HEVC_EXACT_CAPABILITY_TIER_DEFINITIONS[tier]
        .qualificationAccessUnitByteLengths;
    const accessUnits: ArrayBuffer[] = [];
    let byteOffset = 0;
    for (const byteLength of byteLengths) {
        const nextByteOffset = byteOffset + byteLength;
        if (!Number.isSafeInteger(nextByteOffset) || nextByteOffset > bitstream.byteLength) {
            throw new TypeError('The exact HEVC qualification fixture is truncated');
        }
        accessUnits.push(createTransferableBuffer(
            bitstream.subarray(byteOffset, nextByteOffset)
        ));
        byteOffset = nextByteOffset;
    }
    if (byteOffset !== bitstream.byteLength) {
        throw new TypeError('The exact HEVC qualification fixture has trailing bytes');
    }
    return accessUnits;
}

/** Creates a fresh exact single-frame access unit without loading throughput media. */
export function createHEVCExactCapabilityAccessUnit(
    tier: HEVCExactCapabilityTier
): ArrayBuffer {
    return createTransferableBuffer(decodeBase64(ACCESS_UNIT_BASE64[tier]));
}

/** Creates fresh transferable access units for one exact capability probe. */
export function createHEVCExactCapabilityWorkerTierRequests(
    main10UltraHDQualificationBitstream: ArrayBuffer
):
    readonly HEVCExactCapabilityWorkerTierRequest[] {
    if (!(main10UltraHDQualificationBitstream instanceof ArrayBuffer)) {
        throw new TypeError('The exact HEVC 4K qualification fixture is unavailable');
    }
    const requests: HEVCExactCapabilityWorkerTierRequest[] = [];
    for (const tier of HEVC_EXACT_CAPABILITY_TIERS) {
        const definition = HEVC_EXACT_CAPABILITY_TIER_DEFINITIONS[tier];
        requests.push({
            accessUnit: createHEVCExactCapabilityAccessUnit(tier),
            bitDepth: definition.bitDepth,
            codedHeight: definition.codedHeight,
            codedWidth: definition.codedWidth,
            levelIDC: definition.levelIDC,
            maximumDecodeMilliseconds: definition.maximumDecodeMilliseconds,
            minimumFramesPerSecond: definition.minimumFramesPerSecond,
            profileIDC: definition.profileIDC,
            qualificationAccessUnits: createQualificationAccessUnits(
                tier,
                main10UltraHDQualificationBitstream
            ),
            qualificationFrameCount: definition.qualificationFrameCount,
            warmupFrameCount: definition.warmupFrameCount,
            tier
        });
    }
    return requests;
}
